#if UNITY_EDITOR
using System;
using System.IO;
using UnityEngine;
namespace LivingTable.Editor {
 public static class AutoCalibrationTests {
  static void Check(bool ok,string why){if(!ok)throw new Exception("AUTO CALIBRATION: "+why);}
  static LivingTable.Chess.ChessCheckerFit.Frame Synthetic(Vector3 eye,Vector3 center,float size,float yaw,bool checker){var f=new LivingTable.Chess.ChessCheckerFit.Frame{width=320,height=240,camera=eye,rotation=Quaternion.LookRotation(center-eye),fx=.9f,fy=1.2f,cx=.5f,cy=.5f,pixels=new Color32[320*240]};var plane=new Plane(Vector3.up,center);var inverse=Quaternion.Inverse(Quaternion.Euler(0,yaw,0));for(int y=0;y<240;y++)for(int x=0;x<320;x++){var ray=f.Ray(new Vector2(x/319f,y/239f));byte shade=90;if(checker&&plane.Raycast(ray,out float distance)){var p=inverse*(ray.GetPoint(distance)-center);if(Mathf.Abs(p.x)<size*.5f&&Mathf.Abs(p.z)<size*.5f){int col=Mathf.FloorToInt((p.x/size+.5f)*8),row=Mathf.FloorToInt((p.z/size+.5f)*8);shade=(byte)((col+row)%2==0?35:220);}}f.pixels[y*320+x]=new Color32(shade,shade,shade,255);}return f;}
  public static void Run(){var center=new Vector3(.04f,.8f,.02f);var frame=Synthetic(new Vector3(.1f,1.5f,-.55f),center,.56f,12,true);var fit=LivingTable.Chess.ChessCheckerFit.Find(frame,new Vector3(0,.8f,0),.56f,0);Check(fit.valid,"Perspective checker detected");Check(Vector3.Distance(fit.center,center)<.022f&&Mathf.Abs(fit.size-.56f)<.02f&&Mathf.Abs(Mathf.DeltaAngle(fit.yaw,12))<3,"Perspective pose/scale recovered: "+fit.center+" "+fit.size+" "+fit.yaw);var blank=Synthetic(new Vector3(.1f,1.5f,-.55f),center,.56f,12,false);Check(!LivingTable.Chess.ChessCheckerFit.Find(blank,center,.56f,0).valid,"Blank table rejected");var bad=fit;bad.center.x+=.1f;Check(!LivingTable.Chess.ChessCheckerFit.Consistent(fit,bad),"Unstable fit rejected");var bytes=new byte[]{1,2,3};using(var sha=System.Security.Cryptography.SHA256.Create()){string pin=BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","");Check(LivingTable.Chess.ChessHostConnection.Matches(bytes,pin),"Paired certificate accepted");Check(!LivingTable.Chess.ChessHostConnection.Matches(new byte[]{3,2,1},pin),"Wrong certificate rejected");}Check(!LivingTable.Chess.ChessHostConnection.Valid(new LivingTable.Chess.ChessMetaVision.Connection{url="http://10.0.0.2:8791",deviceToken="test"}),"Unencrypted LAN refused");File.WriteAllText("Builds/Auto-calibration-tests.txt","PASS: synthetic perspective checker fit, metric size/pose on known plane, blank rejection, unstable fit rejection, certificate pin match/mismatch, unencrypted LAN rejection. Real-board and piece measurements need hardware testing.\n");AlignmentConnectionTests.Run();}
 }
}
#endif
